    {
      "@type": "Question",
      "name": "What are fluted shelves?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Fluted shelves have parallel grooves cut along their front face, which add texture and catch light even when the shelf is empty. Wrydeco's fluted design is the Handmade Fluted Wood Floating Shelf, which also has a scalloped edge and starts at $469.00."
      }
    },
    {
      "@type": "Question",
      "name": "How much does a fluted floating shelf cost at Wrydeco?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Wrydeco's Handmade Fluted Wood Floating Shelf with scalloped edge starts at $469.00. Shelves in Wrydeco's floating wood shelves collection range from $469.00 to $2658.00, depending on design and options."
      }
    },
    {
      "@type": "Question",
      "name": "What sizes do Wrydeco's floating wood shelves come in?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The slim floating wood shelves in Wrydeco's collection are listed in 24\"W x 3.5\"H, 32\"W x 3.5\"H and 48\"W x 3.5\"H, with a depth of 5\" or 7\". Some other shelves in the collection come in larger sizes, such as Medium at 24\" W x 10\" H x 7\" D. Each product page shows the sizes offered on that shelf."
      }
    },
    {
      "@type": "Question",
      "name": "Can I order a floating wood shelf in a custom size?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Some Wrydeco shelves offer a custom size, either smaller than standard or up to 5\" larger. For anything beyond that, Wrydeco asks you to contact them before ordering."
      }
    },
    {
      "@type": "Question",
      "name": "Can Wrydeco hand-carve a name or pattern into a shelf?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Some Wrydeco shelves offer hand-carving: a custom name or text, an image or pattern, or engraved text and image. On the listing where these appear, custom text starts at $626.90 and image/pattern starts at $776.90."
      }
    }
  ]
